// After add, toggle or remove. 'skipped' (saved list unreadable) shows nothing extra: the banner already says so.
function persist(store, todos) {
  return { message: store.save(todos) === 'failed' ? MESSAGES.notSaved : null };
}

// Returns the list to show and the message. Every path except a successful replace returns `current` unchanged.
// Writes only through store.replace, never store.save, so an unreadable saved list is replaced only here.
async function importBackup({ store, current, file, ask }) {
  const keep = (message) => ({ todos: current, message });
  if (file.size > MAX_IMPORT_BYTES) return keep(MESSAGES.fileTooBig);
  let text;
  try {
    text = await file.text();
  } catch {
    return keep(MESSAGES.cannotReadFile);
  }
  const parsed = parseBackup(text);
  if (!parsed.ok) return keep(parsed.message);
  const question = confirmText({ readError: store.readError, current: current.length, incoming: parsed.todos.length });
  if (question !== null && !(await ask(question))) return keep(null);
  if (store.replace(parsed.todos) !== 'saved') return keep(MESSAGES.notSaved);
  return { todos: parsed.todos, message: fill(MESSAGES.imported, { n: parsed.todos.length }) };
}

if (typeof module !== 'undefined') {
  module.exports = {
    MAX_IMPORT_BYTES, MESSAGES, fill, toBackupText, backupFileName, tooBigToImport, parseBackup, confirmText, persist,
    importBackup,
  };
}
// Tests for app/backup.js (plan/2026-10-19-khach-khong-mat-viec.md, commit A). Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const { randomUUID } = require('node:crypto');
const {
  MAX_IMPORT_BYTES, MESSAGES, fill, toBackupText, backupFileName, tooBigToImport, parseBackup, confirmText, persist,
  importBackup,
} = require('../app/backup.js');

const todo = (title, extra = {}) => ({ id: randomUUID(), title, done: false, createdAt: Date.now(), ...extra });
const list = (n) => Array.from({ length: n }, (_, i) => todo(`Việc ${i + 1}`));
const fileOf = (todos) => JSON.stringify({ version: 1, todos });

function fakeStore({ readError = false, saveResult = 'saved', replaceResult = 'saved' } = {}) {
  const calls = { save: [], replace: [] };
  return {
    readError,
    calls,
    save(t) { calls.save.push(t); return saveResult; },
    replace(t) { calls.replace.push(t); return replaceResult; },
  };
}

function fakeFile(text, size = Buffer.byteLength(text)) {
  const file = { size, reads: 0, async text() { file.reads++; return text; } };
  return file;
}

function fakeAsk(answer) {
  const ask = async (q) => { ask.questions.push(q); return answer; };
